fn main() {
    println!("abs(-5) = {}", absolute_value(-5));
    println!("abs(5) = {}", absolute_value(5));
    println!("max(10, 20) = {}", max(10, 20));
}

fn absolute_value(x: i32) -> i32 {
    if x < 0 {
        return -x;  // Early return
    }
    x  // Implicit return of the last expression
}

fn max(a: i32, b: i32) -> i32 {
    if a > b {
        return a;
    }
    b
}

