    let some_string = String::from("yours");
    some_string  // Return value moves ownership to caller
}

fn takes_and_gives_back(a_string: String) -> String {
    a_string  // Return the same string, moving ownership back
}

fn main() {
    let s1 = String::from("hello");

    let (s2, len) = calculate_length(s1);

    println!("The length of '{}' is {}.", s2, len);
}

fn calculate_length(s: String) -> (String, usize) {
    let length = s.len();
    (s, length)  // Return both the string and its length
}

fn main() {
    let s1 = String::from("hello");

    let len = calculate_length(&s1);  // Pass a reference to s1

    println!("The length of '{}' is {}.", s1, len);
    // s1 is still valid because we only borrowed it!
}

fn calculate_length(s: &String) -> usize {
    s.len()
}  // s goes out of scope, but it does not own the data,
   // so nothing is dropped

