fn main() {
    let s = String::from("hello world");

    let hello = &s[0..5];   // Slice from index 0 to 4
    let world = &s[6..11];  // Slice from index 6 to 10

    println!("hello = {}", hello);
    println!("world = {}", world);

    // Shorthand syntax
    let slice1 = &s[..5];   // From start to index 4
    let slice2 = &s[6..];   // From index 6 to end
    let slice3 = &s[..];    // Entire string

    println!("slice1 = {}, slice2 = {}, slice3 = {}", slice1, slice2, slice3);
}

fn main() {
    let my_string = String::from("hello world");

    // Works with String
    let word = first_word(&my_string);
    println!("First word: {}", word);

    // Works with string literals too!
    let my_string_literal = "hello world";
    let word2 = first_word(my_string_literal);
    println!("First word: {}", word2);
}

fn first_word(s: &str) -> &str {
    let bytes = s.as_bytes();

    for (i, &item) in bytes.iter().enumerate() {
        if item == b' ' {
            return &s[0..i];
        }
    }

    &s[..]
}

