fn main() {
    let user1 = User {
        email: String::from("alice@example.com"),
        username: String::from("alice123"),
        active: true,
        sign_in_count: 1,
    };

    // Create user2 based on user1, changing only the email
    let user2 = User {
        email: String::from("bob@example.com"),
        ..user1  // Use the remaining fields from user1
    };

    println!("user2: {} at {}", user2.username, user2.email);
    // user1.username is now invalid (moved)!
}

